class Solution:
    def divisibleTripletCount(self, nums, d):
        from collections import defaultdict
        left = defaultdict(int)
        ans = 0
        n = len(nums)
        for j in range(n):
            for k in range(j + 1, n):
                ans += left[(-(nums[j] + nums[k])) % d]
            left[nums[j] % d] += 1
        return ans

