class Solution {
public:
    int divisibleTripletCount(vector<int>& nums, int d) {
        unordered_map<long long, long long> left;
        long long ans = 0;
        int n = nums.size();
        for (int j = 0; j < n; j++) {
            for (int k = j + 1; k < n; k++) {
                long long r = ((-(long long)nums[j] - nums[k]) % d + d) % d;
                auto it = left.find(r);
                if (it != left.end()) ans += it->second;
            }
            left[((long long)nums[j] % d + d) % d]++;
        }
        return (int)ans;
    }
};

