class Solution {
    public int divisibleTripletCount(int[] nums, int d) {
        Map<Long, Long> left = new HashMap<>();
        long ans = 0;
        int n = nums.length;
        for (int j = 0; j < n; j++) {
            for (int k = j + 1; k < n; k++) {
                long r = ((-(long) nums[j] - nums[k]) % d + d) % d;
                ans += left.getOrDefault(r, 0L);
            }
            long rem = ((long) nums[j] % d + d) % d;
            left.merge(rem, 1L, Long::sum);
        }
        return (int) ans;
    }
}

