var divisibleTripletCount = function(nums, d) {
    const left = new Map();
    let ans = 0;
    const mod = (x) => ((x % d) + d) % d;
    for (let j = 0; j < nums.length; j++) {
        for (let k = j + 1; k < nums.length; k++) {
            const r = mod(-nums[j] - nums[k]);
            ans += left.get(r) || 0;
        }
        const rem = mod(nums[j]);
        left.set(rem, (left.get(rem) || 0) + 1);
    }
    return ans;
};
